const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const signature = $input.first().json.headers['x-signature'];
const timestamp = Number($input.first().json.headers['x-timestamp']);
const rawBody = JSON.stringify($input.first().json.body);
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
if (!signature || Math.abs(Date.now() - timestamp) > 5 * 60 * 1000 || signature !== expected) {
  throw new Error('Invalid or stale webhook signature');
}
const body = $input.first().json.body;
return [{ json: { icpId: body.payload.icpId, runId: body.payload.runId, orgId: body.payload.orgId } }];

